# FILE: code_executor.py
# Executes approved Python code generated by Groq GPT-OSS 120B.
# Runs the script in a subprocess with a timeout, captures stdout as the spoken result,
# and blocks dangerous patterns before execution.
import os
import re
import ast
import tempfile
import subprocess
import uuid
from logger import get_logger
from config import CODE_EXEC_TIMEOUT

_log = get_logger(__name__)
print = _log.info

# Patterns that are permanently forbidden. Matched case-insensitively against the code.
BLOCKED_PATTERNS = [
    r"format\s+[a-zA-Z]:",
    r"c:\\windows\\system32",
    r"rmdir.*c:\\windows",
    r"del.*c:\\windows",
    r"__import__\s*\(",
    r"\beval\s*\(",
    r"\bexec\s*\(",
    r"os\.system\s*\(",
    r"invoke-expression.*download",
    r"remove-item.*c:\\windows",
    r"\.secrets",
    r"secrets\.enc",
    r"security\.vault",
    r"groq_api_key",
    r"gemini_api_key",
    r"cloudflare_api",
    r"cryptunprotectdata",
]

_BACKEND_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def _python_executable() -> str:
    """Prefer the project venv interpreter, fall back to system python."""
    candidate = os.path.join(_BACKEND_DIR, ".venv", "Scripts", "python.exe")
    if os.path.exists(candidate):
        return candidate
    return "python"


def _is_blocked(code: str) -> bool:
    code_lower = code.lower()
    return any(re.search(p, code_lower) for p in BLOCKED_PATTERNS)


class _GeneratedCodeValidator(ast.NodeVisitor):
    """Reject access to Jarvis internals and dynamic code loading.

    This complements the pattern checks by blocking straightforward import and
    dynamic-loading paths into the secrets vault and assistant internals.
    """

    BLOCKED_MODULES = {"security", "config", "llm", "tools", "backend"}
    BLOCKED_CALLS = {"eval", "exec", "compile", "__import__", "breakpoint"}

    def __init__(self):
        self.reason = ""

    def _reject(self, reason: str):
        if not self.reason:
            self.reason = reason

    def visit_Import(self, node):
        for alias in node.names:
            root = alias.name.split(".", 1)[0]
            if root in self.BLOCKED_MODULES:
                self._reject(f"blocked import: {alias.name}")
        self.generic_visit(node)

    def visit_ImportFrom(self, node):
        module = (node.module or "").split(".", 1)[0]
        if module in self.BLOCKED_MODULES:
            self._reject(f"blocked import: {node.module}")
        self.generic_visit(node)

    def visit_Call(self, node):
        if isinstance(node.func, ast.Name) and node.func.id in self.BLOCKED_CALLS:
            self._reject(f"blocked call: {node.func.id}")
        self.generic_visit(node)

    def visit_Name(self, node):
        if node.id == "__builtins__":
            self._reject("blocked access to __builtins__")
        self.generic_visit(node)


def validate_generated_code(code: str) -> tuple[bool, str]:
    """Validate generated Python before it is written or executed."""
    if _is_blocked(code):
        return False, "blocked dangerous pattern"
    try:
        tree = ast.parse(code, mode="exec")
    except SyntaxError as exc:
        return False, f"syntax error: {exc.msg}"
    validator = _GeneratedCodeValidator()
    validator.visit(tree)
    if validator.reason:
        return False, validator.reason
    return True, ""


def _clean_environment():
    clean_env = os.environ.copy()
    for key in list(clean_env):
        if any(secret in key.upper() for secret in ("GROQ", "GEMINI", "CLOUDFLARE", "SECRET", "API_KEY", "TOKEN", "VAULT")):
            del clean_env[key]
    clean_env.pop("PYTHONPATH", None)
    clean_env["PYTHONNOUSERSITE"] = "1"
    return clean_env


def _terminate_process_tree(proc):
    if proc.poll() is not None:
        return
    try:
        if os.name == "nt":
            subprocess.run(
                ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                capture_output=True,
                timeout=5,
            )
        else:
            proc.kill()
    except Exception as exc:
        print(f"[CodeExecutor] Failed to terminate timed-out process: {exc}")


def execute_code(params: dict, timeout: int = CODE_EXEC_TIMEOUT) -> str:
    """Execute generated Python code and return its stdout (or a safe error string).

    Accepts a params dict (matching the tool-handler convention) with the source under
    ``code``. Runs synchronously in a subprocess; callers run it in an executor so it
    does not block the asyncio event loop. Never returns tracebacks or stderr to the user.
    """
    code = params.get("code", "") if isinstance(params, dict) else params
    if not code or not code.strip():
        return "An error occurred, boss."

    valid, reason = validate_generated_code(code)
    if not valid:
        print(f"[CodeExecutor] BLOCKED generated code: {reason}")
        return "An error occurred, boss."

    try:
        # Print the generated code to terminal so user can see what Jarvis is doing
        print(f"\n{'='*60}")
        print(f"[CodeExecutor] Generated Python code:")
        print(f"{'-'*60}")
        for i, line in enumerate(code.splitlines(), 1):
            print(f"  {i:3d} | {line}")
        print(f"{'-'*60}")
        print(f"[CodeExecutor] Executing with {timeout}s timeout...")
        print(f"{'='*60}\n")

        with tempfile.TemporaryDirectory(prefix="jarvis_exec_") as temp_dir:
            tmp_path = os.path.join(temp_dir, "script.py")
            with open(tmp_path, "w", encoding="utf-8") as f:
                f.write(code)

            creationflags = subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0
            proc = subprocess.Popen(
                [_python_executable(), tmp_path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                cwd=temp_dir,
                env=_clean_environment(),
                creationflags=creationflags,
            )
            try:
                stdout, stderr = proc.communicate(timeout=timeout)
            except subprocess.TimeoutExpired:
                _terminate_process_tree(proc)
                proc.communicate()
                print(f"[CodeExecutor] Timeout after {timeout}s")
                return "An error occurred, boss."

            result = subprocess.CompletedProcess(proc.args, proc.returncode, stdout, stderr)

        output = result.stdout.strip()
        if result.returncode != 0:
            if result.stderr:
                print(f"[CodeExecutor] stderr: {result.stderr[:500]}")
            print(f"[CodeExecutor] [FAIL] Script exited with code {result.returncode}")
            return "An error occurred, boss."

        print(f"[CodeExecutor] [OUTPUT] {output[:300] if output else '(no output)'}")
        return output[:500] if output else "Done, boss."
    except Exception as e:
        print(f"[CodeExecutor] Error: {e}")
        return "An error occurred, boss."
